const fs = require('node:fs');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const [fixturePath, corePath, out] = process.argv.slice(1);
const fixture = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const {parse, compare} = require('./' + corePath);
const match = fixture.request.match(/\[BEFORE CSV\]\n([\s\S]+?)\[AFTER CSV\]\n([\s\S]+?)\[CHANGE BRIEF\]\n([\s\S]+)$/);
assert.ok(match);
const [before, after, originalBrief] = match.slice(1);
assert.match(originalBrief, /Approve A-01 from 10\.00 to 12\.00\. Keep B-02 unchanged\. Confirm the correct C-03 row/);
const configuration = {keyA:'sku',keyB:'sku',fields:[{a:'price',b:'price',kind:'price'}]};
const findings = compare(parse(before), parse(after), configuration);
const actual = findings.map(({type,key,row,other_row,value,other_value})=>[type,key,row,other_row,value,other_value]);
assert.deepEqual(actual, [
 ['duplicate_key','C-03',4,'','C-03',''],
 ['duplicate_key','C-03',5,'','C-03',''],
 ['price_difference','A-01',2,2,'10.00','12.00'],
 ['price_difference','B-02',3,3,'20.00','25.00']
]);
const counterfactualBrief = originalBrief.replace('Keep B-02 unchanged.', 'Approve B-02 from 20.00 to 25.00.');
const hash = path=>crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex');
const report = {
 fixture:'Fictional before/after catalogue update',
 runtime:process.version,
 command:[process.argv[0],'-e',process._eval,...process.argv.slice(1)],
 inputs:{[fixturePath]:hash(fixturePath),[corePath]:hash(corePath)},
 configuration, findings, originalBrief, counterfactualBrief,
 report_en:[
  'A-01 — Keep 12.00. Both briefs approve the price change flagged in CSV row 2.',
  'B-02 — Correct to 20.00 under the original brief. Keep 25.00 under the counterfactual, which explicitly approves it. The checker flags the same row 3 price difference in both cases.',
  'C-03 — Resolve manually. Both briefs require the catalogue owner to confirm which after-file row is authoritative. The checker flags both rows (4 and 5) and does not pair the duplicate.'
 ],
 report_fr:[
  'A-01 — Conserver 12,00. Les deux consignes approuvent la modification signalée à la ligne 2.',
  'B-02 — Rétablir 20,00 selon la consigne initiale. Conserver 25,00 selon la seconde consigne, qui approuve explicitement ce prix. Le même écart est signalé à la ligne 3.',
  'C-03 — Résoudre manuellement. Le responsable du catalogue doit confirmer laquelle des lignes 4 et 5 du fichier après modification fait foi. Le comparateur signale les deux lignes sans les apparier.'
 ],
 scope_en:'Provide two small synthetic or anonymized CSV excerpts with stable SKU and price columns, plus a brief naming approved changes and any authoritative decisions about ambiguous rows. Receive a per-SKU recommendation with supporting row references and questions for the catalogue owner.',
 scope_fr:'Fournir deux courts extraits CSV fictifs ou anonymisés avec des colonnes SKU et prix stables, et préciser les modifications approuvées ainsi que les décisions qui lèvent les ambiguïtés. Recevoir une recommandation par SKU, les références aux lignes et les questions à soumettre au responsable du catalogue.',
 limits:'Offline fictional input. Decisions are an interpretation of the supplied briefs. No import or file modification performed. Private intake and commercial outcomes were outside this run.'
};
fs.writeFileSync(out, JSON.stringify(report,null,2)+'\n');
const saved = JSON.parse(fs.readFileSync(out,'utf8'));
assert.deepEqual(saved.findings,findings);
console.log(JSON.stringify({out,sha256:hash(out),actual,report_en:saved.report_en}));
